THOUGHT: E.6 needs the message pane to render stable message sub-elements and wire posting, inline editing, deletion, threads, and an emoji grid to the existing REST routes. I’ll replace the message renderer and add delegated handlers so dynamically rendered rows remain interactive after refreshes.
```mswea_bash_command
python3 - <<'PY'
p='/app/static/index.html';s=open(p).read()
a=s.index('async function open2(c)')
b=s.index("\nq('#workspace-create-form')",a)
fn=r'''async function open2(c){if(!c)return;try{if(activeWorkspace){const fresh=await api2('/workspaces/'+activeWorkspace.slug);const found=(fresh.channels||[]).find(z=>String(z.id)===String(c.id));if(found)c=found;}q('#channel-title').textContent=c.name;q('#channel-topic').textContent=c.topic||'';window.currentChannel=c;const x=await api2('/channels/'+c.id+'/messages');const ms=(x.messages||[]).slice().reverse();q('#channel-empty-state').textContent=ms.length?'':'No messages yet — start the conversation.';q('#message-list').innerHTML=ms.map(m=>row(m)).join('')}catch(e){q('#channel-empty-state').textContent=e.message}}
function row(m){const rc=m.reply_count||0;return '<div class="message" data-testid="message" data-id="'+m.id+'"><span class="avatar" data-testid="message-avatar">'+(m.author.username||'?')[0]+'</span><b data-testid="message-author">'+m.author.username+'</b><span class="muted" data-testid="message-time">'+new Date(m.created_at).toLocaleString()+'</span><div data-testid="message-body">'+m.body+'</div>'+(m.edited_at?'<span data-testid="message-edited">edited</span>':'')+(rc?'<span data-testid="reply-count">'+rc+' '+(rc==1?'reply':'replies')+'</span>':'')+'<div class="toolbar"><button type="button" data-testid="edit-message-btn">Edit</button><button type="button" data-testid="delete-message-btn">Delete</button><button type="button" data-testid="open-thread-btn">Thread</button><button type="button" data-testid="reaction-button">🙂</button><div data-testid="emoji-picker" class="emoji-picker" style="display:none">'+['😀','👍','🎉','❤️','🚀','😂','😎','🔥'].map(e=>'<button type="button" data-testid="emoji-option" data-emoji="'+e+'">'+e+'</button>').join('')+'</div></div>'+(m.reactions||[]).map(x=>'<span data-testid="reaction-chip">'+x.emoji+' '+x.count+'</span>').join('')+'</div>'}
'''
